import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.C-si7TFR.js";const m=JSON.parse('{"title":"Projects, roles and credentials","description":"","frontmatter":{"title":"Projects, roles and credentials"},"headers":[],"relativePath":"guide/administration.md","filePath":"guide/administration.md"}'),i={name:"guide/administration.md"};function n(s,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="projects-roles-and-credentials" tabindex="-1">Projects, roles and credentials <a class="header-anchor" href="#projects-roles-and-credentials" aria-label="Permalink to &quot;Projects, roles and credentials&quot;">​</a></h1><h2 id="project-spaces" tabindex="-1">Project spaces <a class="header-anchor" href="#project-spaces" aria-label="Permalink to &quot;Project spaces&quot;">​</a></h2><p>Projects organize agents, workflows, resources and members. Confirm the active project before creating, editing or exporting; a resource name alone does not establish ownership.</p><p>Use the user-management or project entry to create projects, add members and assign roles. Visibility, member sources and available entries vary by role and deployment.</p><h2 id="roles-are-not-the-whole-permission-model" tabindex="-1">Roles are not the whole permission model <a class="header-anchor" href="#roles-are-not-the-whole-permission-model" aria-label="Permalink to &quot;Roles are not the whole permission model&quot;">​</a></h2><ul><li>Administrator, editor, viewer and other roles affect visible menus and action scope.</li><li>Viewing a resource does not imply permission to modify, execute, export or access all underlying data.</li><li>Role menus do not imply row- or field-level authorization and do not replace tool-directory restrictions or remote-channel allowlists.</li></ul><p>Before sharing a resource, confirm which roles can see it. Inspect credentials, addresses, instructions and business data before exporting.</p><h2 id="credentials-and-models" tabindex="-1">Credentials and models <a class="header-anchor" href="#credentials-and-models" aria-label="Permalink to &quot;Credentials and models&quot;">​</a></h2><ol><li>Create a credential for the appropriate service in the controlled credential-management entry.</li><li>Generate a distinct secret at the provider with only the required permissions.</li><li>Enter it in local credential configuration, never in public Markdown, screenshots or example repositories.</li><li>Select the credential in the intended node or configuration and test with a no-side-effect request.</li><li>Revoke or rotate secrets when access changes or exposure occurs, then inspect references.</li></ol><p>Model configuration is available from the agent conversation&#39;s model settings entry. Availability depends on provider, network, project configuration and deployment.</p><h2 id="tool-and-data-boundaries" tabindex="-1">Tool and data boundaries <a class="header-anchor" href="#tool-and-data-boundaries" aria-label="Permalink to &quot;Tool and data boundaries&quot;">​</a></h2><p>File, SSH, script, HTTP and MCP capabilities interact with real systems. Use least privilege, fixed directories and destination allowlists. Bind parameters; never concatenate user input into commands or SQL. Remote channels require user allowlists; a hidden URL is not authentication.</p>',12)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
